INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (6, 0, 0, "vo_minigame_1013_top_talk_6_001", "vo_minigame_1013", "", 6010, "", "", 21, "");
INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (6, 1, 6, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 129911, 0, 6011, 0.8, 0, 11, 0);
INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (6, "", "", "", 0, "", 6012, "", "", 91, "");
