INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (6, 0, 0, "vo_minigame_1013_top_talk_6_002", "vo_minigame_1013", "", 6015, "", "", 21, "");
INSERT INTO `v1_2f4b5440e4df55c94ac66d11964b374f912a4cabc79282aa38e032f71830505f` VALUES (6, 1, 9, "いやいや何でもない！\nあたしは別に変なこと\n考えてないからな！\nそれより訓練だっ！", 129811, 0, 6016, 0.3, 0, 11, 0);
